    <script>
        const socket = new WebSocket('ws://localhost:8080');

        socket.onopen = () => {
            console.log('Connected to server');
        };

        socket.onmessage = (event) => {
            const data = JSON.parse(event.data);
            updateCursor(data.userId, data.cursorPosition);
        };

        function updateCursor(userId, cursorPosition) {
            // Update the UI to show the cursor position for each user
            console.log(`User ${userId} is at cursor position:`, cursorPosition);
        }

        function updateCursorPosition() {
            const cursorPosition = { line: 1, column: 0 };
