    </script>
</body>
</html>
```

##### Server-Side Implementation (Node.js):
```javascript
const WebSocket = require('ws');
const { MongoClient } = require('mongodb');

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', async function connection(ws) {
    const uri = "your_mongodb_connection_string";
    const client = new MongoClient(uri);
    await client.connect();
    const database = client.db('vscode_live_share');
    const collection = database.collection('editor_state');

    ws.on('message', async function incoming(message) {
        const data = JSON.parse(message);

        // Save cursor position to the database
        await collection.updateOne({ userId: data.userId }, { $set: { cursorPosition: data.cursorPosition } }, { upsert: true });

        // Broadcast updated cursor position to all other clients
        wss.clients.forEach(function each(client) {
            if (client !== ws && client.readyState === WebSocket.OPEN) {
                client.send(JSON.stringify({ userId: data.userId, cursorPosition: data.cursorPosition }));
            }
        });
    });

    ws.on('close', async function close() {
        // Remove user from database
        await collection.deleteOne({ userId: 'user1' });
    });

    await client.close();
});
```

